package ngl.relay.core;
public final class ClaudeNode extends HttpNode { public static final String DEFAULT_BASE="https://api.anthropic.com/v1",DEFAULT_MODEL="claude-3-5-haiku-20241022",VERSION="2023-06-01"; private final int maxTokens; public ClaudeNode(String id,String key,String base,String model,Integer max){super(id,key,"anthropic-claude",blank(base)?DEFAULT_BASE:base.trim(),blank(model)?DEFAULT_MODEL:model.trim());maxTokens=max==null?2048:max;} private static boolean blank(String s){return s==null||s.trim().isEmpty();} protected void configureAuth(java.net.HttpURLConnection c){c.setRequestProperty("x-api-key",apiKey);} protected void configureHeaders(java.net.HttpURLConnection c){c.setRequestProperty("anthropic-version",VERSION);} public String endpoint(){return baseUrl+"/messages";} public String label(){return "Claude ("+model+")";} protected String requestBody(String p){return "{\"model\":"+esc(model)+",\"max_tokens\":"+maxTokens+",\"messages\":[{\"role\":\"user\",\"content\":"+esc(p)+"}]}";} protected String extractContent(String b)throws NodeException{String x=jsonStringField(b,"text");if(x==null)throw new NodeException("claude bad response json",200,b);return x;} }
